window.addEventListener("scroll",function(){if(!document.getElementById("headerfixed"))return;pageYOffset>200?document.getElementById("headerfixed").style.top=0:document.getElementById("headerfixed").style.top="-200px";let e=$(window).scrollTop()+Math.round($(window).height()/2),t=null;$(".anchors-list a").each(function(){let i=$(this).attr("href");$(i).length&&parseInt($(i).offset().top)<e&&(t=$(this).closest(".slick-slide").data("slick-index"))}),t&&$(".anchors-list").slick("slickGoTo",t)}),document.addEventListener("DOMContentLoaded",function(e){let t=document.querySelectorAll(".anchors-list a");for(let e=0;e<t.length;e++)t[e].addEventListener("click",function(e){e.preventDefault();var t=$(this);let i=this.attributes.href.value;i.length&&($("html, body").animate({scrollTop:$(i).offset().top-$("#headerfixed").height()},1e3),setTimeout(function(){$(".anchors-list").slick("slickGoTo",t.closest(".slick-slide").data("slick-index"))},1100))});$("#headerfixed").on("dblclick",function(){$("html, body").animate({scrollTop:0},500)}),$(".anchors-list").slick({variableWidth:!0,infinite:!1,prevArrow:"",nextArrow:"",centerMode:!0})});